// ECO opening naming + book-deviation detection (spec B / ADR-0028). Pure
// longest-prefix match over a bundled CC0 table. A seed table ships in
// public/openings/eco.json; the full set is regenerated by scripts/build-eco.mjs
// from the Lichess chess-openings TSVs (same seed→ETL pattern as the puzzle DB).

export interface EcoEntry {
  eco: string;
  name: string;
  /** Opening line as UCI moves from the start position. */
  uci: string[];
}

export interface OpeningName {
  eco: string;
  name: string;
  /** Number of plies covered by the matched book line (= first out-of-book ply index). */
  plyInBook: number;
}

/** The deepest book line that is a prefix of (or equals) the played moves. */
export function nameOpening(uci: string[], table: EcoEntry[]): OpeningName | null {
  let best: EcoEntry | null = null;
  for (const e of table) {
    if (e.uci.length > uci.length) continue;
    let prefix = true;
    for (let i = 0; i < e.uci.length; i++) {
      if (e.uci[i] !== uci[i]) { prefix = false; break; }
    }
    if (prefix && (!best || e.uci.length > best.uci.length)) best = e;
  }
  return best ? { eco: best.eco, name: best.name, plyInBook: best.uci.length } : null;
}

/** Ply index at which the game leaves all known book lines (0 if none matched). */
export function firstOutOfBook(uci: string[], table: EcoEntry[]): number {
  return nameOpening(uci, table)?.plyInBook ?? 0;
}

// --- runtime loader (bundled JSON) ----------------------------------------
let cache: EcoEntry[] | null = null;
export async function loadEco(): Promise<EcoEntry[]> {
  if (cache) return cache;
  try {
    const base = (import.meta as { env?: { BASE_URL?: string } }).env?.BASE_URL ?? '/';
    const res = await fetch(`${base}openings/eco.json`);
    cache = res.ok ? ((await res.json()) as EcoEntry[]) : [];
  } catch {
    cache = [];
  }
  return cache;
}

/** Convenience: load the table and name the line in one call. */
export async function describeOpening(uci: string[]): Promise<OpeningName | null> {
  return nameOpening(uci, await loadEco());
}
